import csv
import io


def parse_csv(raw_csv: str):
    """Parse semicolon-delimited CSV with one header and preserve ragged rows."""
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    stream = io.StringIO(raw_csv, newline="")
    reader = csv.reader(stream, delimiter=";", quotechar='"', doublequote=True)

    columns = None
    for record in reader:
        if record:
            columns = record
            break

    if columns is None:
        return {"columns": [], "rows": []}

    rows = list(reader)
    width = max(4, len(columns))
    for row in rows:
        width = max(width, len(row))

    used_names = set(columns)
    while len(columns) < width:
        base = f"column_{len(columns) + 1}"
        name = base
        suffix = 2
        while name in used_names:
            name = f"{base}_{suffix}"
            suffix += 1
        columns.append(name)
        used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
